#!/usr/bin/env node
/** @internal — not part of @hirobius/design-system public API surface. */
/**
 * generate-docs-components — writes content/docs/components/*.mdx (one page per
 * core component) and content/docs/guides/providers.mdx from the component data.
 * Both paths are gitignored: they are build output, regenerated by
 * `pnpm docs:prepare`, so they cannot go stale. The logic lives in
 * scripts/lib/docs-component-pages.mjs (tested in tests/docs-site/).
 *
 *   pnpm docs:components
 */
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CORE_COMPONENTS } from './lib/core-components.mjs';
import {
  buildComponentPages,
  buildProvidersGuide,
  patternComponents,
} from './lib/docs-component-pages.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const rules = JSON.parse(readFileSync(path.join(ROOT, 'scripts/docs-rules.json'), 'utf8'));
const apiPath = path.join(ROOT, 'src/app/data/component-api.json');
if (!existsSync(apiPath)) {
  console.error(`generate-docs-components: ${apiPath} is missing — run \`pnpm docs:api\` first.`);
  process.exit(1);
}
const manifest = JSON.parse(readFileSync(path.join(ROOT, 'public/hds-manifest.json'), 'utf8'));
const api = JSON.parse(readFileSync(apiPath, 'utf8'));
const providers = rules.providerComponents;

const outDir = path.join(ROOT, rules.contentRoot, 'components');
rmSync(outDir, { recursive: true, force: true });
mkdirSync(outDir, { recursive: true });
const pages = buildComponentPages({
  manifest,
  api,
  core: CORE_COMPONENTS,
  providers,
  utilities: rules.utilityComponents,
  utilityPage: rules.utilityPage,
});
for (const [slug, mdx] of pages) writeFileSync(path.join(outDir, `${slug}.mdx`), mdx);

const patternsDir = path.join(ROOT, rules.contentRoot, 'patterns');
rmSync(patternsDir, { recursive: true, force: true });
mkdirSync(patternsDir, { recursive: true });
const patternNames = patternComponents(readFileSync(path.join(ROOT, 'src/patterns.ts'), 'utf8'));
const patternPages = buildComponentPages({
  manifest,
  api,
  core: patternNames,
  section: 'patterns',
  entry: '@hirobius/design-system/patterns',
});
for (const [slug, mdx] of patternPages) writeFileSync(path.join(patternsDir, `${slug}.mdx`), mdx);

const guideFile = path.join(ROOT, rules.contentRoot, rules.providerGuide);
mkdirSync(path.dirname(guideFile), { recursive: true });
writeFileSync(guideFile, buildProvidersGuide({ manifest, providers }));

console.log(
  `generate-docs-components: ${pages.size} component pages, ${patternPages.size} pattern pages + providers guide`,
);
